package bpe

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"testing"
)

// the fixtures are generated by scripts/dump_gpt2_tokenizer_fixtures.py from
// the real tokenizer. comparing against them is the only way to know this
// implementation is right -> a wrong tokenizer still produces perfectly valid
// token ids, so there is nothing to notice by eye

type gpt2Fixtures struct {
	ByteToUnicode map[string]string `json:"byte_to_unicode"`
	EOSTokenID    int               `json:"eos_token_id"`
	VocabSize     int               `json:"vocab_size"`
	Cases         []struct {
		Name    string `json:"name"`
		Text    string `json:"text"`
		IDs     []int  `json:"ids"`
		Decoded string `json:"decoded"`
	} `json:"cases"`
	SingleByteCases []struct {
		Byte int   `json:"byte"`
		IDs  []int `json:"ids"`
	} `json:"single_byte_cases"`
}

func loadFixtures(t *testing.T) *gpt2Fixtures {
	t.Helper()

	path := filepath.Join("testdata", "gpt2_tokenizer_fixtures.json")
	raw, err := os.ReadFile(path)
	if err != nil {
		t.Skipf("fixtures missing (%v) -> run: python scripts/dump_gpt2_tokenizer_fixtures.py", err)
	}

	var fixtures gpt2Fixtures
	if err := json.Unmarshal(raw, &fixtures); err != nil {
		t.Fatalf("fixtures are not valid json: %v", err)
	}

	return &fixtures
}

// the tokenizer files are not in the repo (they are downloadable and the vocab
// is 1MB), so every test that needs them skips rather than fails when they are
// absent. the byte table and pre-tokenizer tests do not need them at all
func loadTestTokenizer(t *testing.T) *GPT2Tokenizer {
	t.Helper()

	for _, dir := range []string{
		filepath.Join("..", "models", "gpt2-medium"),
		filepath.Join("..", "models", "gpt2"),
	} {
		vocab := filepath.Join(dir, "vocab.json")
		merges := filepath.Join(dir, "merges.txt")
		if _, err := os.Stat(vocab); err != nil {
			continue
		}
		if _, err := os.Stat(merges); err != nil {
			continue
		}

		tokenizer, err := LoadGPT2Tokenizer(vocab, merges)
		if err != nil {
			t.Fatalf("found tokenizer files in %s but could not load them: %v", dir, err)
		}
		return tokenizer
	}

	t.Skip("no vocab.json + merges.txt found under models/ -> download them to run this test")
	return nil
}

func TestGPT2ByteRuneTablesMatchReference(t *testing.T) {
	// no tokenizer files needed: this is the fixed 256 entry table, and
	// checking it against the reference means we are not trusting a
	// transcription of the range arithmetic
	fixtures := loadFixtures(t)

	byteToRune, runeToByte := buildByteRuneTables()

	if len(fixtures.ByteToUnicode) != 256 {
		t.Fatalf("expected 256 byte mappings in the fixtures, got %d", len(fixtures.ByteToUnicode))
	}

	for key, expected := range fixtures.ByteToUnicode {
		var b int
		if _, err := fmt.Sscanf(key, "%d", &b); err != nil {
			t.Fatalf("fixture key %q is not a byte value", key)
		}

		got := string(byteToRune[b])
		if got != expected {
			t.Errorf("byte %d: expected %q (U+%04X), got %q (U+%04X)",
				b, expected, []rune(expected)[0], got, byteToRune[b])
		}
	}

	// and the inverse has to be complete, or decoding silently drops bytes
	if len(runeToByte) != 256 {
		t.Errorf("the inverse table should have 256 entries, got %d -> two bytes map to the same rune", len(runeToByte))
	}
	for b := 0; b < 256; b++ {
		if runeToByte[byteToRune[b]] != byte(b) {
			t.Errorf("byte %d does not survive the round trip through the rune tables", b)
		}
	}

	// the space is the one everybody recognises: 0x20 -> U+0120, the Ġ that
	// is all over vocab.json
	if byteToRune[' '] != 0x0120 {
		t.Errorf("expected a space to map to U+0120, got U+%04X", byteToRune[' '])
	}
}

func TestGPT2EncodeMatchesReference(t *testing.T) {
	fixtures := loadFixtures(t)
	tokenizer := loadTestTokenizer(t)

	for _, c := range fixtures.Cases {
		got := tokenizer.Encode(c.Text)

		if len(got) != len(c.IDs) {
			t.Errorf("%s: %q\n  expected %d ids %v\n  got      %d ids %v",
				c.Name, c.Text, len(c.IDs), c.IDs, len(got), got)
			continue
		}

		for i := range c.IDs {
			if got[i] != c.IDs[i] {
				t.Errorf("%s: %q\n  expected %v\n  got      %v\n  first difference at index %d",
					c.Name, c.Text, c.IDs, got, i)
				break
			}
		}
	}
}

func TestGPT2DecodeMatchesReference(t *testing.T) {
	fixtures := loadFixtures(t)
	tokenizer := loadTestTokenizer(t)

	for _, c := range fixtures.Cases {
		got := tokenizer.Decode(c.IDs)
		if got != c.Decoded {
			t.Errorf("%s: decoding %v\n  expected %q\n  got      %q", c.Name, c.IDs, c.Decoded, got)
		}
	}
}

func TestGPT2RoundTrip(t *testing.T) {
	fixtures := loadFixtures(t)
	tokenizer := loadTestTokenizer(t)

	// byte level BPE promises decode(encode(x)) == x for anything, including
	// text it has never seen and bytes that are not valid utf-8
	for _, c := range fixtures.Cases {
		if got := tokenizer.Decode(tokenizer.Encode(c.Text)); got != c.Text {
			t.Errorf("%s: round trip changed the text\n  in  %q\n  out %q", c.Name, c.Text, got)
		}
	}
}

func TestGPT2EveryByteRoundTrips(t *testing.T) {
	fixtures := loadFixtures(t)
	tokenizer := loadTestTokenizer(t)

	if len(fixtures.SingleByteCases) != 256 {
		t.Fatalf("expected 256 single byte cases, got %d", len(fixtures.SingleByteCases))
	}

	for _, c := range fixtures.SingleByteCases {
		// latin-1 is how the fixture generator turned each byte into text,
		// so we rebuild the same string here
		text := string(rune(c.Byte))
		if c.Byte > 127 {
			// a byte above 127 as latin-1 becomes a two byte utf-8 sequence,
			// which is exactly what python produced
			text = string(rune(c.Byte))
		}

		got := tokenizer.Encode(text)
		if len(got) != len(c.IDs) {
			t.Errorf("byte %d (%q): expected %v, got %v", c.Byte, text, c.IDs, got)
			continue
		}
		for i := range c.IDs {
			if got[i] != c.IDs[i] {
				t.Errorf("byte %d (%q): expected %v, got %v", c.Byte, text, c.IDs, got)
				break
			}
		}
	}
}

func TestGPT2VocabSizeAndEOS(t *testing.T) {
	fixtures := loadFixtures(t)
	tokenizer := loadTestTokenizer(t)

	if tokenizer.VocabSize() != fixtures.VocabSize {
		t.Errorf("expected a vocab of %d, got %d", fixtures.VocabSize, tokenizer.VocabSize())
	}

	// our constant has to agree with the real tokenizer, since generation
	// stops on it
	if GPT2EOSTokenID != fixtures.EOSTokenID {
		t.Errorf("GPT2EOSTokenID is %d but the tokenizer says %d", GPT2EOSTokenID, fixtures.EOSTokenID)
	}
}

func TestSplitPiecesHandlesTheLookaheadRule(t *testing.T) {
	// no tokenizer files needed. this is the branch Go cannot express as a
	// regex, so it gets its own direct test with the expectations spelled out
	cases := []struct {
		name     string
		input    string
		expected []string
	}{
		{"simple", "The area of Antarctica is", []string{"The", " area", " of", " Antarctica", " is"}},
		// the lookahead: the LAST space of a run joins the following word
		{"two spaces", "hello  world", []string{"hello", " ", " world"}},
		{"three spaces", "a   b", []string{"a", "  ", " b"}},
		// a run with nothing after it stays whole
		{"trailing", "trailing spaces   ", []string{"trailing", " spaces", "   "}},
		{"only spaces", "    ", []string{"    "}},
		// a single tab or newline before a word is NOT absorbed, because the
		// optional leading character in the pattern is a literal space
		{"tab", "tabs\tand", []string{"tabs", "\t", "and"}},
		{"newline", "a\nb", []string{"a", "\n", "b"}},
		// a CR LF pair is a two character run before a word, so the rule holds
		// and splits it: the first N-1 go together, the last stands alone.
		// verified against the real regex, which does the same
		{"crlf", "one\r\ntwo", []string{"one", "\r", "\n", "two"}},
		{"double crlf", "a\r\n\r\nb", []string{"a", "\r\n\r", "\n", "b"}},
		{"blank line", "a\n\nb", []string{"a", "\n", "\n", "b"}},
		// contractions win over the letter branch
		{"contraction", "don't", []string{"don", "'t"}},
		{"possessive", "Alice's", []string{"Alice", "'s"}},
		{"uppercase contraction", "DON'T", []string{"DON", "'", "T"}},
		// digits and symbols form their own runs
		{"number", "km2", []string{"km", "2"}},
		{"punctuation", "wait... really?!", []string{"wait", "...", " really", "?!"}},
		{"empty", "", nil},
		{"single space", " ", []string{" "}},
		{"leading space", " hello", []string{" hello"}},
	}

	for _, c := range cases {
		got := splitPieces(c.input)

		if len(got) != len(c.expected) {
			t.Errorf("%s: %q\n  expected %q\n  got      %q", c.name, c.input, c.expected, got)
			continue
		}
		for i := range c.expected {
			if got[i] != c.expected[i] {
				t.Errorf("%s: %q\n  expected %q\n  got      %q", c.name, c.input, c.expected, got)
				break
			}
		}
	}
}

func TestSplitPiecesNeverLosesCharacters(t *testing.T) {
	// whatever the splitting rules do, concatenating the pieces has to give
	// the input back. an off by one in the whitespace branch would silently
	// drop a space, which is the kind of thing that is invisible until the
	// model starts answering a slightly different question
	inputs := []string{
		"The area of Antarctica is",
		"hello  world",
		"a   b   c",
		"   leading and trailing   ",
		"tabs\t\tand\n\nnewlines",
		"don't it's I'm they'll",
		"戦場のヴァルキュリア3",
		"that is wild \U0001f525\U0001f680",
		"role @-@ playing video game",
		"",
		" ",
		"\n",
		"a",
	}

	for _, input := range inputs {
		var rebuilt string
		for _, piece := range splitPieces(input) {
			rebuilt += piece
		}
		if rebuilt != input {
			t.Errorf("pieces do not reassemble\n  in  %q\n  out %q", input, rebuilt)
		}
	}
}

func TestGPT2TokenizerRejectsBadFiles(t *testing.T) {
	dir := t.TempDir()

	vocab := filepath.Join(dir, "vocab.json")
	merges := filepath.Join(dir, "merges.txt")

	if err := os.WriteFile(vocab, []byte(`{"a":0,"b":1}`), 0644); err != nil {
		t.Fatalf("unexpected error: %v", err)
	}

	// a merges file with no usable lines should be refused rather than
	// producing a tokenizer that silently never merges anything
	if err := os.WriteFile(merges, []byte("#version: 0.2\n"), 0644); err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if _, err := LoadGPT2Tokenizer(vocab, merges); err == nil {
		t.Errorf("expected an error for a merges file with no merges")
	}

	// a malformed merge line too
	if err := os.WriteFile(merges, []byte("#version: 0.2\na b c\n"), 0644); err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if _, err := LoadGPT2Tokenizer(vocab, merges); err == nil {
		t.Errorf("expected an error for a merge line with three symbols")
	}

	if _, err := LoadGPT2Tokenizer(filepath.Join(dir, "nope.json"), merges); err == nil {
		t.Errorf("expected an error for a missing vocab file")
	}
}
